<?php header("Content-Type: application/json"); use PHPMailer\PHPMailer\PHPMailer; use PHPMailer\PHPMailer\Exception; require 'vendor/autoload.php'; // Only POST request if ($_SERVER["REQUEST_METHOD"] !== "POST") { echo json_encode([ "status" => "error", "message" => "Invalid request method." ]); exit; } // Get JSON data $data = json_decode( file_get_contents("php://input"), true ); // Check data if (!$data) { echo json_encode([ "status" => "error", "message" => "No data received." ]); exit; } // Form data $name = trim($data["name"] ?? ""); $email = trim($data["email"] ?? ""); $message = trim($data["message"] ?? ""); // Validate if ($name === "" || $email === "" || $message === "") { echo json_encode([ "status" => "error", "message" => "Please fill all fields." ]); exit; } // Validate email if (!filter_var($email, FILTER_VALIDATE_EMAIL)) { echo json_encode([ "status" => "error", "message" => "Invalid email address." ]); exit; } $mail = new PHPMailer(true); try { // SMTP settings $mail->isSMTP(); $mail->Host = "smtp.gmail.com"; $mail->SMTPAuth = true; // YOUR GMAIL $mail->Username = "amarfzd12@gmail.com"; // YOUR GOOGLE APP PASSWORD $mail->Password = "YOUR_16_DIGIT_APP_PASSWORD"; $mail->SMTPSecure = PHPMailer::ENCRYPTION_STARTTLS; $mail->Port = 587; // Sender $mail->setFrom( "amarfzd12@gmail.com", "Amarsweb Contact Form" ); // Receiver $mail->addAddress( "amarfzd12@gmail.com", "Amar Singh" ); // Visitor email $mail->addReplyTo( $email, $name ); // Email $mail->isHTML(true); $mail->Subject = "New Contact Form Message - " . $name; $mail->Body = " <h2>New Website Contact Message</h2> <p> <strong>Name:</strong> " . htmlspecialchars($name) . " </p> <p> <strong>Email:</strong> " . htmlspecialchars($email) . " </p> <p> <strong>Project Details:</strong> </p> <p> " . nl2br(htmlspecialchars($message)) . " </p> "; // Send $mail->send(); echo json_encode([ "status" => "success", "message" => "Message sent successfully." ]); } catch (Exception $e) { echo json_encode([ "status" => "error", "message" => "Mailer Error: " . $mail->ErrorInfo ]); } ?>
